        "type": "notebook",
        "content": "type: notebook\napp_id: code\nskill_id: notebook\nlanguage: python\nfilename: berlin_bike_ride_forecast.ipynb\ncell_count: 10\nembed_ref: berlin_bike_ride_forecast.ipynb-b7ea93\nstatus: finished\nsource_version: null\nnotebook:\n  nbformat: 4\n  nbformat_minor: 5\n  metadata:\n    kernelspec:\n      display_name: Python 3\n      language: python\n      name: python3\n    language_info:\n      name: python\n  cells[10]:\n    - cell_type: markdown\n      metadata:\n      source: \"# 🚴 Berlin Weekend Bike Ride Weather Forecast\\n\\nThis notebook fetches hourly weather forecast data from the free [Open-Meteo API](https://open-meteo.com/) for Berlin. It analyzes key cycling metrics—**temperature**, **precipitation**, **wind speed**, and **cloud cover**—to assess whether the upcoming weekend is suitable for a long bike ride.\"\n    - cell_type: code\n      execution_count: null\n      metadata:\n      outputs[0]:\n      source: \"import requests\\nimport pandas as pd\\nimport matplotlib.pyplot as plt\\n\\n# Configure plot styling\\nplt.style.use('seaborn-v0_8-whitegrid' if 'seaborn-v0_8-whitegrid' in plt.style.available else 'default')\\nplt.rcParams['figure.figsize'] = (12, 6)\\n\\n# Coordinates for Berlin, Germany\\nBERLIN_LAT = 52.5200\\nBERLIN_LON = 13.4050\\n\\nprint(\\\"Libraries imported successfully!\\\")\"\n    - cell_type: markdown\n      metadata:\n      source: ## 1. Fetch Forecast Data from Open-Meteo API\n    - cell_type: code\n      execution_count: null\n      metadata:\n      outputs[0]:\n      source: \"# Build request parameters for 7-day hourly forecast\\nurl = \\\"https://api.open-meteo.com/v1/forecast\\\"\\nparams = {\\n    \\\"latitude\\\": BERLIN_LAT,\\n    \\\"longitude\\\": BERLIN_LON,\\n    \\\"hourly\\\": [\\\"temperature_2m\\\", \\\"precipitation\\\", \\\"wind_speed_10m\\\", \\\"cloud_cover\\\"],\\n    \\\"timezone\\\": \\\"Europe/Berlin\\\",\\n    \\\"forecast_days\\\": 7\\n}\\n\\nresponse = requests.get(url, params=params)\\nresponse.raise_for_status()\\ndata = response.json()\\n\\n# Parse hourly data into pandas DataFrame\\ndf_hourly = pd.DataFrame(data['hourly'])\\ndf_hourly['time'] = pd.to_datetime(df_hourly['time'])\\ndf_hourly['date'] = df_hourly['time'].dt.date\\ndf_hourly['hour'] = df_hourly['time'].dt.hour\\ndf_hourly['day_name'] = df_hourly['time'].dt.day_name()\\ndf_hourly['is_weekend'] = df_hourly['time'].dt.dayofweek.isin([5, 6])\\n\\ndf_hourly.head()\"\n    - cell_type: markdown\n      metadata:\n      source: \"## 2. Filter Daytime Hours & Compute Daily Summaries\\n\\nFor cycling, daytime hours (8:00 AM – 8:00 PM) are most relevant.\"\n    - cell_type: code\n      execution_count: null\n      metadata:\n      outputs[0]:\n      source: \"# Filter for daylight cycling hours (08:00 to 20:00)\\ndaytime_df = df_hourly[(df_hourly['hour'] >= 8) & (df_hourly['hour'] <= 20)].copy()\\n\\n# Calculate daily summary metrics\\ndaily_summary = daytime_df.groupby(['date', 'day_name', 'is_weekend']).agg(\\n    temp_min=('temperature_2m', 'min'),\\n    temp_max=('temperature_2m', 'max'),\\n    temp_avg=('temperature_2m', 'mean'),\\n    total_rain_mm=('precipitation', 'sum'),\\n    max_rain_hour_mm=('precipitation', 'max'),\\n    avg_wind_kmh=('wind_speed_10m', 'mean'),\\n    max_wind_kmh=('wind_speed_10m', 'max'),\\n    avg_cloud_cover=('cloud_cover', 'mean')\\n).reset_index()\\n\\n# Round numerical columns for clean presentation\\ndaily_summary = daily_summary.round(1)\\n\\n# Evaluate suitability score for cycling (Ideal: temp 15-25°C, rain < 0.5mm, wind < 20km/h)\\ndef evaluate_ride_conditions(row):\\n    score = 10\\n    # Penalty for rain\\n    if row['total_rain_mm'] > 2.0:\\n        score -= 5\\n    elif row['total_rain_mm'] > 0.2:\\n        score -= 2\\n        \\n    # Penalty for high wind\\n    if row['max_wind_kmh'] > 30:\\n        score -= 3\\n    elif row['max_wind_kmh'] > 20:\\n        score -= 1\\n        \\n    # Penalty for cold/hot temperatures\\n    if row['temp_max'] < 10 or row['temp_max'] > 32:\\n        score -= 3\\n    elif row['temp_max'] < 15:\\n        score -= 1\\n        \\n    if score >= 8:\\n        return \\\"🟢 Great\\\"\\n    elif score >= 5:\\n        return \\\"🟡 Moderate\\\"\\n    else:\\n        return \\\"🔴 Poor\\\"\\n\\ndaily_summary['ride_rating'] = daily_summary.apply(evaluate_ride_conditions, axis=1)\\n\\nprint(\\\"--- Daily Forecast Summary (Daytime 08:00-20:00) ---\\\")\\ndisplay(daily_summary)\"\n    - cell_type: markdown\n      metadata:\n      source: ## 3. Visualizations\n    - cell_type: code\n      execution_count: null\n      metadata:\n      outputs[0]:\n      source: \"fig, axes = plt.subplots(2, 1, figsize=(14, 10), sharex=True)\\n\\n# Plot 1: Temperature & Rain\\nax1 = axes[0]\\nax1_rain = ax1.twinx()\\n\\nline1 = ax1.plot(df_hourly['time'], df_hourly['temperature_2m'], color='tab:orange', linewidth=2, label='Temp (°C)')\\nbar1 = ax1_rain.bar(df_hourly['time'], df_hourly['precipitation'], color='tab:blue', alpha=0.5, width=0.03, label='Rain (mm)')\\n\\nax1.set_ylabel('Temperature (°C)', color='tab:orange', fontsize=12)\\nax1_rain.set_ylabel('Precipitation (mm)', color='tab:blue', fontsize=12)\\nax1.set_title('Berlin 7-Day Hourly Temperature & Precipitation', fontsize=14, fontweight='bold')\\n\\n# Plot 2: Wind Speed & Cloud Cover\\nax2 = axes[1]\\nax2_cloud = ax2.twinx()\\n\\nline2 = ax2.plot(df_hourly['time'], df_hourly['wind_speed_10m'], color='tab:red', linewidth=1.8, label='Wind Speed (km/h)')\\nfill2 = ax2_cloud.fill_between(df_hourly['time'], 0, df_hourly['cloud_cover'], color='gray', alpha=0.25, label='Cloud Cover (%)')\\n\\nax2.set_ylabel('Wind Speed (km/h)', color='tab:red', fontsize=12)\\nax2_cloud.set_ylabel('Cloud Cover (%)', color='tab:gray', fontsize=12)\\nax2.set_title('Berlin 7-Day Hourly Wind Speed & Cloud Cover', fontsize=14, fontweight='bold')\\nax2.set_xlabel('Date / Time', fontsize=12)\\n\\n# Highlight Weekend Days\\nfor ax in [ax1, ax2]:\\n    weekend_days = df_hourly[df_hourly['is_weekend']]['date'].unique()\\n    for w_date in weekend_days:\\n        start_time = pd.to_datetime(f\\\"{w_date} 00:00\\\")\\n        end_time = pd.to_datetime(f\\\"{w_date} 23:59\\\")\\n        ax.axvspan(start_time, end_time, color='green', alpha=0.08)\\n\\nplt.tight_layout()\\nplt.show()\"\n    - cell_type: markdown\n      metadata:\n      source: \"## 4. Weekend Bike Ride Recommendation\\n\\nLet's highlight the upcoming Saturday and Sunday specifically to see if conditions are good for riding.\"\n    - cell_type: code\n      execution_count: null\n      metadata:\n      outputs[0]:\n      source: \"weekend_summary = daily_summary[daily_summary['is_weekend']]\\n\\nprint(\\\"=== Weekend Forecast Breakdown ===\\\")\\nfor _, row in weekend_summary.iterrows():\\n    print(f\\\"\\\\n📅 {row['day_name']} ({row['date']}): Rating -> {row['ride_rating']}\\\")\\n    print(f\\\"   • Temperature Range: {row['temp_min']}°C to {row['temp_max']}°C (Avg: {row['temp_avg']}°C)\\\")\\n    print(f\\\"   • Total Daytime Rain: {row['total_rain_mm']} mm (Max hourly: {row['max_rain_hour_mm']} mm)\\\")\\n    print(f\\\"   • Wind: Avg {row['avg_wind_kmh']} km/h (Gults/Max: {row['max_wind_kmh']} km/h)\\\")\\n    print(f\\\"   • Cloud Cover: Avg {row['avg_cloud_cover']}%\\\")\\n\\n# Summary Recommendation\\nbest_day = weekend_summary.sort_values(by=['total_rain_mm', 'avg_wind_kmh']).iloc[0]\\nprint(f\\\"\\\\n💡 Summary Recommendation:\\\")\\nprint(f\\\"The best day for a bike ride this weekend is likely **{best_day['day_name']} ({best_day['date']})**.\\\")\"",
